import sys

def generate_color_code(n, P):
    def backtrack(path):
        if len(path) == 1 << n:
            return True
        last = path[-1]
        for i in range(1 << n):
            diff = bin(last ^ i).count('1')
            if diff in P:
                path.append(i)
                if backtrack(path):
                    return True
                path.pop()
        return False

    for start in range(1 << n):
        if bin(start).count('1') in P:
            path = [start]
            if backtrack(path):
                return '\n'.join(format(num, f'0{n}b') for num in path)
    return "impossible"

